"""Работа с деньгами.

Внутри системы суммы хранятся в копейках (int), чтобы не ловить ошибки округления float.
В рубли переводим только на выходе отчёта.
"""
from decimal import ROUND_HALF_UP, Decimal


def to_kopecks(value: str) -> int:
    """'1234.50' -> 123450"""
    return int((Decimal(value) * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def to_rubles(kopecks: int) -> float:
    """123450 -> 1234.5"""
    return round(kopecks / 100, 2)


def split_evenly(total: int, parts: int) -> list[int]:
    """Делит сумму в копейках на parts частей. Лишние копейки достаются первым частям."""
    if parts <= 0:
        raise ValueError("parts must be positive")
    base, rest = divmod(total, parts)
    return [base + (1 if i < rest else 0) for i in range(parts)]

"""Конфигурация клиента: clients/<slug>.toml."""
from __future__ import annotations

import tomllib
from dataclasses import dataclass, field
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CLIENTS_DIR = ROOT / "clients"


@dataclass
class ClientConfig:
    slug: str
    name: str
    partner_channels: list[str]
    clubs: dict[int, dict] = field(default_factory=dict)

    def club(self, club_id: int) -> dict:
        """Настройки конкретного клуба (пустой словарь, если их нет)."""
        return self.clubs.get(club_id, {})


def load_config(slug: str, clients_dir: Path = CLIENTS_DIR) -> ClientConfig:
    with open(clients_dir / f"{slug}.toml", "rb") as f:
        raw = tomllib.load(f)
    clubs = {int(club_id): settings for club_id, settings in raw.get("clubs", {}).items()}
    return ClientConfig(
        slug=slug,
        name=raw["name"],
        partner_channels=raw["import"]["partner_channels"],
        clubs=clubs,
    )

